class Rfq(TypedDict):
  """A Request for Quote (RFQ) lets a taker solicit private quotes on a single instrument from makers. Single instrument: Each RFQ targets one instrument (kind = STABLE_PERP) for a single requested size. The taker may disclose a direction via `rfq.side`, or omit it to request a two-way (buy and sell) quote. Maker solicitation: On submission, GRVT broadcasts the RFQ to makers over the `v1.rfq` feed (see RfqFeed). Makers respond with private quotes, which the taker receives as a private quote book over the `v1.quote` feed (see RfqQuoteFeed). Anonymity: Anonymity is automatic and always enforced — the taker and makers only ever see each other's derived anonymous account ids. Real taker and maker identities are never exposed to the counterparty. Expiry: The RFQ lives until `rfq.expiry`, after which GRVT expires it and auto-cancels the makers' private quotes bound to it."""

  rfq_id: str
  """[Filled by GRVT Backend] A unique 128-bit identifier for the RFQ, deterministically generated within the GRVT backend."""
  sub_account_id: str
  """The subaccount initiating the RFQ."""
  expiry: TimestampNanos
  """RFQ TTL. The timestamp after which Gravity expires the RFQ. Default 60s, cap 300s (per-instrument config)"""
  instrument: str
  """The instrument to trade. Must be kind = STABLE_PERP."""
  size: Decimal
  """Requested size (positive), expressed in base asset decimal units."""
  side: NotRequired[Literal['UNSPECIFIED', 'BUY', 'SELL']]
  """Optional — omitted = two-way request. The GRVT UI always fills it; API takers may withhold direction and accept two-way quotes."""


