class LimitOrder(TypedDict):
  """A limit order: every leg carries a limit price (the venue refuses one without, `2021`)."""

  is_market: NotRequired[Literal[False]]
  """Not a market order; may be left out."""
  sub_account_id: NotRequired[str]
  """The subaccount initiating the order. Defaults to the client's trading sub-account when omitted."""
  time_in_force: Literal[
    'GOOD_TILL_TIME',
    'ALL_OR_NONE',
    'IMMEDIATE_OR_CANCEL',
    'FILL_OR_KILL',
    'RETAIL_PRICE_IMPROVEMENT',
  ]
  """Four supported types of orders: GTT, IOC, AON, FOK: PARTIAL EXECUTION = GTT / IOC - allows partial size execution on each leg; FULL EXECUTION = AON / FOK - only allows full size execution on all legs; TAKER ONLY = IOC / FOK - only allows taker orders; MAKER OR TAKER = GTT / AON - allows maker or taker orders. The exchange supports GTT, IOC and FOK; an RFQ maker GTT and AON, an RFQ taker IOC and FOK. `RETAIL_PRICE_IMPROVEMENT` is a GTT post-only maker order: it signs fine, and an account without RPI permission is refused with `1001`."""
  post_only: NotRequired[bool]
  """If True, Order must be a maker order. It has to fill the orderbook instead of match it. If False, Order can be either a maker or taker order. In this case, order creation is currently subject to a speedbump of 25ms to ensure orders are matched against updated orderbook quotes. | | Must Fill All | Can Fill Partial | | - | - | - | | Must Be Taker | FOK + False | IOC + False | | Can Be Either | AON + False | GTC + False | | Must Be Maker | AON + True | GTC + True |."""
  reduce_only: NotRequired[bool]
  """If True, Order must reduce the position size, or be cancelled."""
  signature: NotRequired[Signature | PinnedSignature]
  """Omit it (or pin only `expiration`/`nonce`) to have the client sign the order; pass a full signature to send a pre-signed one. For a `GOOD_TILL_TIME` order the signature expiration is the order's expiry."""
  metadata: NewOrderMetadata
  """Order Metadata, ignored by the smart contract, and unsigned by the client."""
  builder: NotRequired[str]
  """The main account ID of the builder. Leave it out for an order with no builder."""
  builder_fee: NotRequired[PlainDecimal | str]
  """Builder fee charged for this order, expressed as a percentage (e.g., 0.001 means 0.001%). Only with `builder`."""
  legs: list[LimitOrderLeg]
  """The legs present in this order. The legs must be sorted by Asset.Instrument/Underlying/Quote/Expiration/StrikePrice."""


class MarketOrder(TypedDict):
  """A market order: a taker order with no limit price, executed at the maker prices."""

  is_market: Literal[True]
  """A market order."""
  sub_account_id: NotRequired[str]
  """The subaccount initiating the order. Defaults to the client's trading sub-account when omitted."""
  time_in_force: Literal[
    'GOOD_TILL_TIME', 'ALL_OR_NONE', 'IMMEDIATE_OR_CANCEL', 'FILL_OR_KILL'
  ]
  """Four supported types of orders: GTT, IOC, AON, FOK: PARTIAL EXECUTION = GTT / IOC - allows partial size execution on each leg; FULL EXECUTION = AON / FOK - only allows full size execution on all legs; TAKER ONLY = IOC / FOK - only allows taker orders; MAKER OR TAKER = GTT / AON - allows maker or taker orders. The exchange supports GTT, IOC and FOK; an RFQ maker GTT and AON, an RFQ taker IOC and FOK. `RETAIL_PRICE_IMPROVEMENT`, a post-only maker order, does not apply to a market order."""
  post_only: NotRequired[Literal[False]]
  """A market order is always a taker order, never post-only: `false`, or left out."""
  reduce_only: NotRequired[bool]
  """If True, Order must reduce the position size, or be cancelled."""
  signature: NotRequired[Signature | PinnedSignature]
  """Omit it (or pin only `expiration`/`nonce`) to have the client sign the order; pass a full signature to send a pre-signed one. For a `GOOD_TILL_TIME` order the signature expiration is the order's expiry."""
  metadata: NewOrderMetadata
  """Order Metadata, ignored by the smart contract, and unsigned by the client."""
  builder: NotRequired[str]
  """The main account ID of the builder. Leave it out for an order with no builder."""
  builder_fee: NotRequired[PlainDecimal | str]
  """Builder fee charged for this order, expressed as a percentage (e.g., 0.001 means 0.001%). Only with `builder`."""
  legs: list[MarketOrderLeg]
  """The legs present in this order. The legs must be sorted by Asset.Instrument/Underlying/Quote/Expiration/StrikePrice."""


class Order(TypedDict):
  """Order is a typed payload used throughout the GRVT platform to express all orderbook, RFQ, and liquidation orders. GRVT orders are capable of expressing both single-legged, and multi-legged orders by default. This increases the learning curve slightly but reduces overall integration load, since the order payload is used across all GRVT trading venues. Given GRVT's trustless settlement model, the Order payload also carries the signature, required to trade the order on our ZKSync Hyperchain. All fields in the Order payload (except `id`, `metadata`, and `state`) are trustlessly enforced on our Hyperchain. This minimizes the amount of trust users have to offer to GRVT."""

  order_id: NotRequired[str]
  """[Filled by GRVT Backend] A unique 128-bit identifier for the order, deterministically generated within the GRVT backend."""
  sub_account_id: str
  """The subaccount initiating the order."""
  is_market: NotRequired[bool]
  """If the order is a market order. Market Orders do not have a limit price, and are always executed according to the maker order price. Market Orders must always be taker orders. On STABLE_PERP a slippage bound is mandatory: `limit_price` must carry the signed bound (reference price ± the chosen slippage), otherwise the order is rejected with `STABLE_PERP_REQUIRES_PRICE_BOUND`. is_market = false with a limit price behaves identically on STABLE_PERP; the flag is intent metadata only."""
  time_in_force: Literal[
    'GOOD_TILL_TIME',
    'ALL_OR_NONE',
    'IMMEDIATE_OR_CANCEL',
    'FILL_OR_KILL',
    'RETAIL_PRICE_IMPROVEMENT',
  ]
  """Four supported types of orders: GTT, IOC, AON, FOK: PARTIAL EXECUTION = GTT / IOC - allows partial size execution on each leg; FULL EXECUTION = AON / FOK - only allows full size execution on all legs; TAKER ONLY = IOC / FOK - only allows taker orders; MAKER OR TAKER = GTT / AON - allows maker or taker orders. The exchange supports GTT, IOC and FOK; an RFQ maker GTT and AON, an RFQ taker IOC and FOK."""
  post_only: NotRequired[bool]
  """If True, Order must be a maker order. It has to fill the orderbook instead of match it. If False, Order can be either a maker or taker order. In this case, order creation is currently subject to a speedbump of 25ms to ensure orders are matched against updated orderbook quotes. | | Must Fill All | Can Fill Partial | | - | - | - | | Must Be Taker | FOK + False | IOC + False | | Can Be Either | AON + False | GTC + False | | Must Be Maker | AON + True | GTC + True |."""
  reduce_only: NotRequired[bool]
  """If True, Order must reduce the position size, or be cancelled."""
  legs: list[OrderLeg]
  """The legs present in this order. The legs must be sorted by Asset.Instrument/Underlying/Quote/Expiration/StrikePrice."""
  signature: Signature
  """The signature approving this order."""
  metadata: OrderMetadata
  """Order Metadata, ignored by the smart contract, and unsigned by the client."""
  state: NotRequired[OrderState]
  """[Filled by GRVT Backend] The current state of the order, ignored by the smart contract, and unsigned by the client."""
  builder: str
  """The main account ID of the builder. The zero address (`0x0000000000000000000000000000000000000000`) when the order has no builder; `""` on the orders of a bulk create reply."""
  builder_fee: Decimal | Literal['']
  """Builder fee charged for this order, expressed as a percentage (e.g., 0.001 means 0.001%). `""` (unset) on the orders of a bulk create reply."""


NewOrder = LimitOrder | MarketOrder
